import pandas as pd


def run(inputs: dict) -> dict:
    dim = inputs["dim_account"].copy()
    stg = inputs["stg_account"].copy()

    # Build per-account list of version dicts from current dim state
    versions: dict = {}
    for acc_id, group in dim.groupby("account_id"):
        vlist = []
        for _, row in group.iterrows():
            vlist.append({
                "plan": row["plan"],
                "eff_start_date": row["eff_start_date"],
                "eff_end_date": row["eff_end_date"],
                "is_current": row["is_current"],
            })
        versions[acc_id] = vlist

    def plans_equal(a, b):
        a_na = pd.isna(a)
        b_na = pd.isna(b)
        if a_na and b_na:
            return True
        if a_na or b_na:
            return False
        return a == b

    stg_sorted = stg.sort_values(["account_id", "update_date"], kind="stable")

    for _, s in stg_sorted.iterrows():
        acc_id = s["account_id"]
        plan = s["plan"]
        update_date = s["update_date"]

        if acc_id not in versions or len(versions[acc_id]) == 0:
            versions.setdefault(acc_id, [])
            versions[acc_id].append({
                "plan": plan,
                "eff_start_date": update_date,
                "eff_end_date": pd.NaT,
                "is_current": 1,
            })
            continue

        vlist = versions[acc_id]

        # find the version covering update_date
        v = None
        for ver in vlist:
            start = ver["eff_start_date"]
            end = ver["eff_end_date"]
            if start <= update_date and (pd.isna(end) or update_date < end):
                v = ver
                break

        if v is None:
            # update_date is earlier than the account's first version
            f = min(vlist, key=lambda x: x["eff_start_date"])
            vlist.append({
                "plan": plan,
                "eff_start_date": update_date,
                "eff_end_date": f["eff_start_date"],
                "is_current": 0,
            })
        else:
            if plans_equal(v["plan"], plan):
                # unchanged - no-op
                pass
            elif update_date == v["eff_start_date"]:
                # same-day correction, no new version
                v["plan"] = plan
            else:
                # split v at update_date
                vlist.append({
                    "plan": plan,
                    "eff_start_date": update_date,
                    "eff_end_date": v["eff_end_date"],
                    "is_current": v["is_current"],
                })
                v["eff_end_date"] = update_date
                v["is_current"] = 0

    rows = []
    for acc_id, vlist in versions.items():
        for ver in vlist:
            rows.append({
                "account_id": acc_id,
                "plan": ver["plan"],
                "eff_start_date": ver["eff_start_date"],
                "eff_end_date": ver["eff_end_date"],
                "is_current": ver["is_current"],
            })

    out = pd.DataFrame(
        rows,
        columns=["account_id", "plan", "eff_start_date", "eff_end_date", "is_current"],
    )

    if len(out) > 0:
        out["account_id"] = out["account_id"].astype("int64")
        out["is_current"] = out["is_current"].astype("int64")
        out["eff_start_date"] = pd.to_datetime(out["eff_start_date"])
        out["eff_end_date"] = pd.to_datetime(out["eff_end_date"])

    return {"dim_account_out": out}
